def _seed_rows(counts, yvals):
    """Create alternating half-cell-offset rows for a staggered layered seed."""
    rows = []
    for row, (m, y) in enumerate(zip(counts, yvals)):
        # Center each row, then offset alternate layers by half of their
        # horizontal cell width.  Clipping keeps every seed center strictly
        # inside the square, while preserving the triangular-lattice pattern.
        spacing = 1.0 / m
        xs = (np.arange(m, dtype=float) + 0.5) * spacing
        if row % 2:
            xs += 0.5 * spacing
        xs = np.clip(xs, 0.045, 0.955)
        rows.extend((float(x), float(y)) for x in xs)
    return np.asarray(rows, dtype=float)
